<template>
	<div class="post-detail-container">
		<!-- 头部区域 -->
		<div class="header">
			<div class="back-button">
				<i class="icon-back">←</i>
			</div>
			<div class="user-info">
				<img class="avatar" :src="postData.avatar" alt="">
				<span class="username">{{ postData.username }}</span>
			</div>
		</div>

		<!-- 主内容区域 -->
		<div class="content">
			<swiper class="image-swiper" :indicator-dots="true" :autoplay="false" circular>
				<swiper-item v-for="(imageUrl, index) in postData.images" :key="index">
					<image :src="imageUrl" mode="aspectFill" class="slide-image"></image>
				</swiper-item>
			</swiper>

			<!-- 描述信息 -->
			<view class="description">
				<view class="description-title">{{ postData.title }}</view>
				<view class="description-content">{{ postData.content }}</view>
			</view>

			<!-- "不喜欢"按钮 -->
			<view class="dislike-btn">
				<text class="dislike-icon">♡</text>
				<text>不喜歡</text>
			</view>

			<!-- 评论区域 -->
			<view class="comment-section">
				<view class="comment-item" v-for="(comment, index) in postData.comments" :key="index">
					<view class="comment-header">
						<image class="comment-avatar" :src="comment.avatar"></image>
						<text class="comment-username">{{ comment.username }}:</text>
					</view>
					<view class="comment-text">
						{{ comment.text }}
					</view>
					<view class="comment-actions" v-if="comment.replyVisible">
						<text class="reply-btn">回复</text>
					</view>
				</view>

				<!-- 输入评论框 -->
				<view class="comment-input-area">
					<input class="comment-input" placeholder="评论：" @focus="onCommentFocus" v-model="newComment" />
					<button class="send-btn" @click="sendComment">发送</button>
				</view>
			</view>
		</div>

		<!-- 底部操作栏 -->
		<div class="bottom-bar">
			<view class="like-count">
				<i class="icon-like">♥</i>
				<text>{{ postData.likeCount }}</text>
			</view>
			<view class="comment-count">
				<i class="icon-comment">💬</i>
				<text>{{ postData.commentCount }}</text>
			</view>
		</div>
	</div>
</template>

<script>
	export default {
		name: 'PostDetail',
		props: {
			postData: {
				type: Object,
				required: true,
				default: () => ({
					username: "小李",
					avatar: "/images/avatar.png",
					images: ["/images/post-image.jpg"],
					title: "周末与朋友欢聚",
					content: "这个周末和朋友们一起度过了愉快的时光！\n美食、欢笑、美好的回忆，一切都太棒了！",
					likeCount: 13,
					commentCount: 7,
					comments: [{
							avatar: "/images/commenter1.png",
							username: "小王",
							text: "哇哇哇好丰盛！！！",
							replyVisible: false
						},
						{
							avatar: "/images/commenter2.png",
							username: "小张",
							text: "",
							replyVisible: true
						}
					]
				})
			}
		},
		data() {
			return {
				newComment: ""
			};
		},
		methods: {
			onCommentFocus() {
				// 焦点处理逻辑
			},
			sendComment() {
				if (this.newComment.trim()) {
					const newCommentObj = {
						avatar: "/images/user-avatar.png", // 当前用户头像
						username: "我",
						text: this.newComment,
						replyVisible: false
					};

					this.$emit('add-comment', newCommentObj);
					this.newComment = "";
				}
			}
		}
	};
</script>

<style lang="scss" scoped>
