		font-weight: 500;
	}

	.content {
		flex: 1;
		overflow-y: auto;
		padding: 0 15px;
	}

	.image-swiper {
		width: 100%;
		height: 400rpx;
		margin-bottom: 20px;
	}

	.slide-image {
		width: 100%;
		height: 100%;
	}

	.description {
		margin-bottom: 20px;
	}

	.description-title {
