		font-size: 14px;
		margin-bottom: 20px;
	}

	.dislike-icon {
		margin-right: 5px;
		font-size: 16px;
	}

	.comment-section {
		margin-top: 20px;
	}

	.comment-item {
		margin-bottom: 15px;
		padding-bottom: 15px;
		border-bottom: 1px solid #eee;
	}

	.comment-header {
		display: flex;
		align-items: center;
		margin-bottom: 5px;
	}

	.comment-avatar {
		width: 35px;
		height: 35px;
		border-radius: 50%;
		margin-right: 8px;
	}

	.comment-username {
		font-weight: 500;
	}

	.comment-text {
		margin-left: 43px;
