		color: #333;
	}

	.bottom-bar {
		display: flex;
		justify-content: flex-end;
		align-items: center;
		padding: 15px 20px;
		background-color: #fff;
		border-top: 1px solid #eee;
	}

	.like-count,
	.comment-count {
		display: flex;
